-- DataSetName=ATVChannelDayPart / VisualizationType=MultiLineChartCard
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'ATVChannelDayPart' AND [VisualizationType] = N'MultiLineChartCard')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'SELECT
      CONVERT(NVARCHAR, XAxisLabel) AS XAxisLabel
      ,DENSE_RANK() OVER(ORDER BY CAST(XAxisLabel AS INT)) AS LabelSort
      ,Value
      ,DENSE_RANK() OVER(ORDER BY Value) AS ValueSort
      ,VisId
      ,''line'' AS VisType
      ,LegendLabel
  FROM
  (
  SELECT
      CAST(DATEPART(HOUR, F.[LINEITEM_TIMESTAMP]) AS NVARCHAR) AS XAxisLabel,
      ROUND(
          SUM(CASE WHEN F.[LI_TYPE] = ''TENDER'' THEN F.[GROSS_VALUE] ELSE 0 END)
          / NULLIF(SUM(CASE WHEN F.[LI_TYPE] = ''TENDER'' THEN F.[ORDER_COUNT] ELSE 0 END), 0)
      , 2) AS Value,
      1 AS VisId,
      COALESCE(channel.[BOTTOM_MICROSERVICE_NAME], channel.[BOTTOM_CHANNEL_NAME]) AS LegendLabel
  FROM
      [presentation].[F_LINEITEM_15MIN] F
  INNER JOIN [presentation].[CALENDAR] C ON F.[ORDER_DATE] = C.[DATE]
  LEFT JOIN [presentation].[D_LOCATION] location ON F.LOCATION_HUB_ID = location.BOTTOM_HUB_ID
  LEFT JOIN [presentation].[D_REVCENTER] revcenter ON F.REVCENTER_HUB_ID = revcenter.BOTTOM_HUB_ID
