  WHERE 1=1
  AND COALESCE(channel.[BOTTOM_MICROSERVICE_NAME], channel.[BOTTOM_CHANNEL_NAME]) IS NOT NULL
  @FilterClause
  GROUP BY
      DATEPART(HOUR, F.[LINEITEM_TIMESTAMP]),
      COALESCE(channel.[BOTTOM_MICROSERVICE_NAME], channel.[BOTTOM_CHANNEL_NAME])
  HAVING SUM(CASE WHEN F.[LI_TYPE] = ''TENDER'' THEN F.[ORDER_COUNT] ELSE 0 END) > 0
  ) SUB


  SELECT
  ''Hour of Day'' AS XAxisLabel,
  ''ATV ('' + NCHAR(163) + '')'' AS YAxisLabel,
  ''Average Transaction Value'' AS Title,
  ''By Channel'' AS Description,
  NULL AS Trend,
  NULL AS Chip,
  (SELECT ROUND(
      SUM(CASE WHEN F.[LI_TYPE] = ''TENDER'' THEN F.[GROSS_VALUE] ELSE 0 END)
      / NULLIF(SUM(CASE WHEN F.[LI_TYPE] = ''TENDER'' THEN F.[ORDER_COUNT] ELSE 0 END), 0)
  , 2)
