ON ACTUALS.DAY_PERIOD = TEMPLATE.DAY_PERIOD
AND ACTUALS.CHANNEL = TEMPLATE.CHANNEL
) INPUTQUERY

SELECT
    ''Average Transaction Value'' AS [Title]
    ,    ''By Channel'' AS [Description]
    ,    NULL AS [Value]');
