-- DataSetName=BkgActiveUsersByBrand / VisualizationType=MultiLineChartCard
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'BkgActiveUsersByBrand' AND [VisualizationType] = N'MultiLineChartCard')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'SELECT
    XAxisLabel,
    ROW_NUMBER() OVER(ORDER BY MonthStart, VisId) AS LabelSort,
    Value,
    ROW_NUMBER() OVER(ORDER BY Value) AS ValueSort,
    VisId,
    ''linear'' AS Curve,
    ''total'' AS Stack,
    ''false'' AS Area,
    ''ascending'' AS StackOrder,
    ''true'' AS ShowMark,
    LegendLabel
FROM (
    SELECT
        FORMAT(DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1), ''MMM yyyy'') AS XAxisLabel,
        DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1) AS MonthStart,
        SUM(ACTIVE_USERS) AS Value,
        DENSE_RANK() OVER (ORDER BY BRAND_NAME) AS VisId,
        BRAND_NAME AS LegendLabel
    FROM [presentation].[PF_BOOKING_METRICS_HOUR]
    WHERE 1=1 @FilterClause
    AND ACTIVE_USERS IS NOT NULL
    GROUP BY BRAND_NAME, DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1)
) SUB

