        [CreatedBy] = N'mushfiqur.rahman@threerocks.co.uk',
        [ModifiedBy] = N'mushfiqur.rahman@threerocks.co.uk',
        [OutputDefinitions] = N'{"column_mappings": {}, "additional_datasets": []}',
        [ExecutionQuery] = NULL
    WHERE [DataSetName] = N'BkgActiveUsersByBrand' AND [VisualizationType] = N'MultiLineChartCard';
END
