BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'WITH MonthlyData AS (
    SELECT
        BRAND_NAME,
        DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1) AS MonthStart,
        SUM(TOTAL_BOOKINGS) AS Bookings,
        SUM(TOTAL_COVERS) AS Covers,
        SUM(SESSIONS) AS Sessions,
        SUM(ACTIVE_USERS) AS ActiveUsers
    FROM [presentation].[PF_BOOKING_METRICS_HOUR]
    WHERE 1=1 @FilterClause
    GROUP BY BRAND_NAME, DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1)
),
RankedMonths AS (
    SELECT *, DENSE_RANK() OVER (ORDER BY MonthStart DESC) AS MonthRank
    FROM MonthlyData
)
SELECT
    curr.BRAND_NAME AS Column1,
    curr.Bookings AS Column2,
    CASE WHEN prev.Bookings > 0
        THEN ROUND((CAST(curr.Bookings AS FLOAT) - prev.Bookings) / prev.Bookings * 100, 1)
        ELSE NULL END AS Column3,
    curr.Covers AS Column4,
    curr.Sessions AS Column5,
    curr.ActiveUsers AS Column6,
    CASE WHEN curr.Sessions > 0
        THEN ROUND(CAST(curr.Bookings AS FLOAT) / curr.Sessions * 100, 1)
        ELSE NULL END AS Column7,
