    NULL AS Column27, NULL AS Column28, NULL AS Column29
FROM RankedMonths curr
LEFT JOIN RankedMonths prev ON curr.BRAND_NAME = prev.BRAND_NAME AND prev.MonthRank = 2
WHERE curr.MonthRank = 1
ORDER BY curr.Bookings DESC

