        [QueryTemplate] = N'SELECT
    XAxisLabel,
    ROW_NUMBER() OVER(ORDER BY MonthStart, VisId) AS LabelSort,
    Value,
    ROW_NUMBER() OVER(ORDER BY Value) AS ValueSort,
    VisId,
    ''linear'' AS Curve,
    ''total'' AS Stack,
    ''false'' AS Area,
