    SELECT
        FORMAT(DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1), ''MMM yyyy'') AS XAxisLabel,
        DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1) AS MonthStart,
