-- DataSetName=BkgConversionSummary / VisualizationType=CustomDataGrid
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'BkgConversionSummary' AND [VisualizationType] = N'CustomDataGrid')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'WITH LatestMonth AS (
    SELECT MAX(DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1)) AS MonthStart
    FROM [presentation].[PF_BOOKING_METRICS_HOUR]
    WHERE 1=1 @FilterClause
)
SELECT
    BRAND_NAME AS Column1,
    SUM(TOTAL_BOOKINGS) AS Column2,
    SUM(SESSIONS) AS Column3,
    CASE WHEN SUM(SESSIONS) > 0
        THEN ROUND(CAST(SUM(TOTAL_BOOKINGS) AS FLOAT) / SUM(SESSIONS) * 100, 1)
        ELSE NULL END AS Column4,
    CASE WHEN SUM(SESSIONS) > 0
        THEN SUM(SESSIONS) - SUM(TOTAL_BOOKINGS)
        ELSE NULL END AS Column5,
    CASE WHEN SUM(SESSIONS) > 0 THEN
        CASE WHEN CAST(SUM(TOTAL_BOOKINGS) AS FLOAT) / SUM(SESSIONS) * 100 > 7 THEN ''Strong''
             WHEN CAST(SUM(TOTAL_BOOKINGS) AS FLOAT) / SUM(SESSIONS) * 100 > 3 THEN ''Moderate''
             ELSE ''Needs attention'' END
        ELSE NULL END AS Column6,
    NULL AS Column7, NULL AS Column8, NULL AS Column9, NULL AS Column10,
    NULL AS Column11, NULL AS Column12, NULL AS Column13, NULL AS Column14,
    NULL AS Column15, NULL AS Column16, NULL AS Column17, NULL AS Column18,
    NULL AS Column19, NULL AS Column20, NULL AS Column21, NULL AS Column22,
    NULL AS Column23, NULL AS Column24, NULL AS Column25, NULL AS Column26,
    NULL AS Column27, NULL AS Column28, NULL AS Column29
FROM [presentation].[PF_BOOKING_METRICS_HOUR] d
CROSS JOIN LatestMonth lm
WHERE DATEFROMPARTS(YEAR(d.BOOKING_DATE), MONTH(d.BOOKING_DATE), 1) = lm.MonthStart
AND d.SESSIONS IS NOT NULL
AND 1=1 @FilterClause
GROUP BY d.BRAND_NAME
ORDER BY SUM(TOTAL_BOOKINGS) DESC

