-- DataSetName=BkgFastestGrowingBrand / VisualizationType=SingleKPICard
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'BkgFastestGrowingBrand' AND [VisualizationType] = N'SingleKPICard')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'WITH MonthlyBrand AS (
    SELECT BRAND_NAME, DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1) AS MonthStart,
        SUM(TOTAL_BOOKINGS) AS Bookings
    FROM [presentation].[PF_BOOKING_METRICS_HOUR]
    WHERE 1=1 @FilterClause
    GROUP BY BRAND_NAME, DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1)
    HAVING SUM(TOTAL_BOOKINGS) > 0
),
BrandRange AS (
    SELECT BRAND_NAME, MIN(MonthStart) AS FirstMonth, MAX(MonthStart) AS LastMonth
    FROM MonthlyBrand
    GROUP BY BRAND_NAME
    HAVING MIN(MonthStart) < MAX(MonthStart)
),
Growth AS (
    SELECT br.BRAND_NAME,
        ROUND((CAST(l.Bookings AS FLOAT) - f.Bookings) / f.Bookings * 100, 0) AS GrowthPct,
        br.FirstMonth, br.LastMonth
    FROM BrandRange br
    INNER JOIN MonthlyBrand f ON br.BRAND_NAME = f.BRAND_NAME AND f.MonthStart = br.FirstMonth
    INNER JOIN MonthlyBrand l ON br.BRAND_NAME = l.BRAND_NAME AND l.MonthStart = br.LastMonth
)
SELECT TOP 1
    BRAND_NAME AS Value,
    ''Fastest Growing Brand'' AS Title,
    CASE WHEN GrowthPct >= 0 THEN ''+'' + FORMAT(GrowthPct, ''N0'') + ''%''
         ELSE FORMAT(GrowthPct, ''N0'') + ''%'' END
    + '' '' + FORMAT(FirstMonth, ''MMM'') + ''-'' + FORMAT(LastMonth, ''MMM'') AS Subtitle
FROM Growth
ORDER BY GrowthPct DESC',
        [ParameterMappings] = N'{"LocationList": "", "StartDate": "BOOKING_DATE", "EndDate": "BOOKING_DATE"}',
        [FilterDefinitions] = N'{"Brands": {"column": "BRAND_NAME", "type": "IN", "dataType": "VARCHAR"}}',
        [Description] = N'Brand with highest first-to-last month booking growth percentage',
        [CreatedDate] = '2026-04-08 14:18:16.320',
        [ModifiedDate] = '2026-04-09 09:56:30.670',
        [CreatedBy] = N'mushfiqur.rahman@threerocks.co.uk',
        [ModifiedBy] = N'mushfiqur.rahman@threerocks.co.uk',
        [OutputDefinitions] = N'{"column_mappings": {}, "additional_datasets": []}',
        [ExecutionQuery] = NULL
    WHERE [DataSetName] = N'BkgFastestGrowingBrand' AND [VisualizationType] = N'SingleKPICard';
END
ELSE
BEGIN
    INSERT INTO [core].[core].[VisualisationQueries] ([DataSetName], [VisualizationType], [Version], [Status], [QueryTemplate], [ParameterMappings], [FilterDefinitions], [Description], [CreatedDate], [ModifiedDate], [CreatedBy], [ModifiedBy], [OutputDefinitions], [ExecutionQuery])
    VALUES (N'BkgFastestGrowingBrand', N'SingleKPICard', 1, N'LIVE', N'WITH MonthlyBrand AS (
    SELECT BRAND_NAME, DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1) AS MonthStart,
        SUM(TOTAL_BOOKINGS) AS Bookings
    FROM [presentation].[PF_BOOKING_METRICS_HOUR]
    WHERE 1=1 @FilterClause
    GROUP BY BRAND_NAME, DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1)
    HAVING SUM(TOTAL_BOOKINGS) > 0
),
BrandRange AS (
    SELECT BRAND_NAME, MIN(MonthStart) AS FirstMonth, MAX(MonthStart) AS LastMonth
    FROM MonthlyBrand
    GROUP BY BRAND_NAME
    HAVING MIN(MonthStart) < MAX(MonthStart)
),
Growth AS (
    SELECT br.BRAND_NAME,
        ROUND((CAST(l.Bookings AS FLOAT) - f.Bookings) / f.Bookings * 100, 0) AS GrowthPct,
        br.FirstMonth, br.LastMonth
    FROM BrandRange br
    INNER JOIN MonthlyBrand f ON br.BRAND_NAME = f.BRAND_NAME AND f.MonthStart = br.FirstMonth
    INNER JOIN MonthlyBrand l ON br.BRAND_NAME = l.BRAND_NAME AND l.MonthStart = br.LastMonth
)
SELECT TOP 1
    BRAND_NAME AS Value,
    ''Fastest Growing Brand'' AS Title,
    CASE WHEN GrowthPct >= 0 THEN ''+'' + FORMAT(GrowthPct, ''N0'') + ''%''
         ELSE FORMAT(GrowthPct, ''N0'') + ''%'' END
    + '' '' + FORMAT(FirstMonth, ''MMM'') + ''-'' + FORMAT(LastMonth, ''MMM'') AS Subtitle
FROM Growth
ORDER BY GrowthPct DESC', N'{"LocationList": "", "StartDate": "BOOKING_DATE", "EndDate": "BOOKING_DATE"}', N'{"Brands": {"column": "BRAND_NAME", "type": "IN", "dataType": "VARCHAR"}}', N'Brand with highest first-to-last month booking growth percentage', '2026-04-08 14:18:16.320', '2026-04-09 09:56:30.670', N'mushfiqur.rahman@threerocks.co.uk', N'mushfiqur.rahman@threerocks.co.uk', N'{"column_mappings": {}, "additional_datasets": []}', NULL);
