    XAxisLabel
    ,DENSE_RANK() OVER(ORDER BY XAxisLabel) AS LabelSort
    ,Value
    ,ROW_NUMBER() OVER(ORDER BY Value) AS ValueSort
    ,VisId
    ,VisType
    ,LegendLabel
