(
SELECT
    FORMAT(C.[DATE], ''dd MMM yyyy'') AS XAxisLabel
    ,C.[DATE] AS SortDate
    ,ROUND(SUM(F.[GROSS_VALUE]),2) AS Value
    ,1 AS VisId
    ,''bar'' AS VisType
    ,''Total Revenue'' AS LegendLabel
FROM
    [presentation].[F_LINEITEM_15MIN] F

INNER JOIN
    [presentation].[CALENDAR] C
ON F.[ORDER_DATE] = C.[DATE]

LEFT JOIN [presentation].[D_DEAL] deal
ON F.DEAL_HUB_ID = deal.BOTTOM_HUB_ID

LEFT JOIN [presentation].[D_DISCOUNT] discount
    ON F.DISCOUNT_HUB_ID = discount.BOTTOM_HUB_ID

LEFT JOIN [presentation].[D_PRODUCT] product
    ON F.PRODUCT_HUB_ID = product.BOTTOM_HUB_ID

LEFT JOIN [presentation].[D_LOCATION] location
    ON F.LOCATION_HUB_ID = location.BOTTOM_HUB_ID

LEFT JOIN [presentation].[D_REVCENTER] revcenter
    ON F.REVCENTER_HUB_ID = revcenter.BOTTOM_HUB_ID

LEFT JOIN [presentation].[D_CHANNEL] channel
    ON F.CHANNEL_HUB_ID = channel.BOTTOM_HUB_ID

WHERE 1=1
AND F.[LI_TYPE] IN (''PROD'',''MOD'')
@FilterClause

GROUP BY
    FORMAT(C.[DATE], ''dd MMM yyyy'')
    ,C.[DATE]

UNION ALL

SELECT
    FORMAT(C.[DATE], ''dd MMM yyyy'') AS XAxisLabel
    ,C.[DATE] AS SortDate
    ,ROUND(SUM(F.[GROSS_VALUE]),2) AS Value
    ,DENSE_RANK() OVER(ORDER BY COALESCE(product.[TOP_MICROSERVICE_NAME],product.[TOP_NAME])) + 1 AS VisId
    ,''line'' AS VisType
    ,COALESCE(product.[TOP_MICROSERVICE_NAME],product.[TOP_NAME]) AS LegendLabel
FROM
    [presentation].[F_LINEITEM_15MIN] F

INNER JOIN
    [presentation].[CALENDAR] C
ON F.[ORDER_DATE] = C.[DATE]

LEFT JOIN [presentation].[D_DEAL] deal
ON F.DEAL_HUB_ID = deal.BOTTOM_HUB_ID

LEFT JOIN [presentation].[D_DISCOUNT] discount
    ON F.DISCOUNT_HUB_ID = discount.BOTTOM_HUB_ID

LEFT JOIN [presentation].[D_PRODUCT] product
    ON F.PRODUCT_HUB_ID = product.BOTTOM_HUB_ID

LEFT JOIN [presentation].[D_LOCATION] location
    ON F.LOCATION_HUB_ID = location.BOTTOM_HUB_ID

LEFT JOIN [presentation].[D_REVCENTER] revcenter
    ON F.REVCENTER_HUB_ID = revcenter.BOTTOM_HUB_ID

LEFT JOIN [presentation].[D_CHANNEL] channel
    ON F.CHANNEL_HUB_ID = channel.BOTTOM_HUB_ID

WHERE 1=1
AND F.[LI_TYPE] IN (''PROD'',''MOD'')
AND COALESCE(product.[TOP_MICROSERVICE_NAME],product.[TOP_NAME]) IS NOT NULL
@FilterClause

GROUP BY
    FORMAT(C.[DATE], ''dd MMM yyyy'')
    ,C.[DATE]
    ,COALESCE(product.[TOP_MICROSERVICE_NAME],product.[TOP_NAME])

HAVING SUM(F.[GROSS_VALUE]) > 0
