  LEFT JOIN [presentation].[D_REVCENTER] revcenter ON F.REVCENTER_HUB_ID = revcenter.BOTTOM_HUB_ID
  LEFT JOIN [presentation].[D_CHANNEL] channel ON F.CHANNEL_HUB_ID = channel.BOTTOM_HUB_ID
  LEFT JOIN [presentation].[D_DEAL] deal ON F.DEAL_HUB_ID = deal.BOTTOM_HUB_ID
  LEFT JOIN [presentation].[D_DISCOUNT] discount ON F.DISCOUNT_HUB_ID = discount.BOTTOM_HUB_ID
  WHERE F.LI_TYPE = ''PROD''
  AND COALESCE(product.[TOP_MICROSERVICE_NAME], product.[TOP_NAME]) IS NOT NULL
  AND COALESCE(product.[TOP_MICROSERVICE_NAME], product.[TOP_NAME]) != ''Unknown''
  AND 1=1
  @FilterClause
  GROUP BY F.[ORDER_DATE], FORMAT(F.[ORDER_DATE], ''dd MMM yyyy''),
      COALESCE(product.[TOP_MICROSERVICE_NAME], product.[TOP_NAME])
  ) SUB
  ) INPUTQUERY

  SELECT
      ''Date'' AS [XAxisLabel],
      ''Revenue ('' + NCHAR(163) + '')'' AS [YAxisLabel],
      ''Revenue by Category'' AS [Title],
      ''Daily trend — products only, excludes modifiers'' AS [Description]');
END
