-- DataSetName=ClaudeSkillTest / VisualizationType=PieChartCard
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'ClaudeSkillTest' AND [VisualizationType] = N'PieChartCard')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'WITH Sales AS
(
SELECT
    ROUND(SUM(NET_VALUE),2) AS Sales
FROM [presentation].[F_LINEITEM_15MIN] F
INNER JOIN
    [presentation].[CALENDAR] C
ON F.[ORDER_DATE] = C.[DATE]
LEFT JOIN
    [presentation].[D_LOCATION] location
ON F.LOCATION_HUB_ID = location.BOTTOM_HUB_ID
WHERE 1=1
@FilterClause
),
Inventory AS
(
SELECT
    ROUND(SUM(Waste),2) AS Waste
    ,ROUND(SUM(Usage),2) AS Usage
    ,CASE WHEN ROUND(SUM(Variance),2) < 0 THEN ABS(ROUND(SUM(Variance),2)) ELSE 0 END AS NegativeVariance
FROM
    (
    SELECT
        SUM(F.WASTE_VALUE) AS Waste
        ,SUM(F.SALES_VALUE) AS Usage
        ,MAX(F.VARIANCE_VALUE) AS Variance
    FROM [presentation].[F_INVREPORT_DAY] F
    INNER JOIN
        [presentation].[CALENDAR] C
    ON F.[REPORTING_DATE] = C.[DATE]
    LEFT JOIN
        [presentation].[D_LOCATION] location
    ON F.LOCATION_HUB_ID = location.BOTTOM_HUB_ID
    LEFT JOIN
        [presentation].[D_INVITEM] invitem
    ON F.INVITEM_HUB_ID = invitem.BOTTOM_HUB_ID
    WHERE 1=1
    @FilterClause
    GROUP BY
        F.LOCATION_HUB_ID
        ,F.INVITEM_HUB_ID
        ,F.COUNT_GROUP
    ) SUB
)
SELECT
    ''Sales'' AS [Label]
    ,FORMAT(Sales, ''N2'') AS [Value]
    ,1 AS [Id]
    ,''linear'' AS [Curve]
    ,''total'' AS [Stack]
    ,''true'' AS [Area]
    ,''ascending'' AS [StackOrder]
    ,''false'' AS [ShowMark]
    ,''Sales'' AS [LegendLabel]
FROM Sales
UNION ALL
SELECT
    ''Usage'' AS [Label]
    ,FORMAT(Usage, ''N2'') AS [Value]
    ,2 AS [Id]
    ,''linear'' AS [Curve]
    ,''total'' AS [Stack]
    ,''true'' AS [Area]
    ,''ascending'' AS [StackOrder]
    ,''false'' AS [ShowMark]
    ,''Usage'' AS [LegendLabel]
FROM Inventory
UNION ALL
SELECT
    ''Waste'' AS [Label]
    ,FORMAT(Waste, ''N2'') AS [Value]
    ,3 AS [Id]
    ,''linear'' AS [Curve]
    ,''total'' AS [Stack]
    ,''true'' AS [Area]
    ,''ascending'' AS [StackOrder]
    ,''false'' AS [ShowMark]
    ,''Waste'' AS [LegendLabel]
FROM Inventory

SELECT
    ''Sales, Usage & Waste Breakdown'' AS Title
    ,'''' AS Description
    ,NULL AS Trend
    ,NULL AS Chip
    ,(SELECT FORMAT(ROUND(SUM(NET_VALUE),2), ''N0'')
      FROM [presentation].[F_LINEITEM_15MIN] F
      INNER JOIN [presentation].[CALENDAR] C
          ON F.[ORDER_DATE] = C.[DATE]
      LEFT JOIN [presentation].[D_LOCATION] location
          ON F.LOCATION_HUB_ID = location.BOTTOM_HUB_ID
      WHERE 1=1
      @FilterClause) AS PiePrimaryText
    ,''Net Sales'' AS PieSecondaryText',
        [ParameterMappings] = N'{"LocationList":"COALESCE(location.[BOTTOM_MICROSERVICE_NAME],location.[BOTTOM_LOCATION_NAME])","StartDate":"C.[DATE]","EndDate":"C.[DATE]"}',
        [FilterDefinitions] = N'{"Channels":{"column":"","type":"IN","dataType":"VARCHAR"},"DayOfWeek":{"column":"","type":"IN","dataType":"VARCHAR"},"DealToggle":{"column":"","type":"IN","dataType":"VARCHAR"},"Deals":{"column":"","type":"IN","dataType":"VARCHAR"},"Discounts":{"column":"","type":"IN","dataType":"VARCHAR"},"Distributors":{"column":"","type":"IN","dataType":"VARCHAR"},"Integrations":{"column":"","type":"IN","dataType":"VARCHAR"},"InvItems":{"column":"","type":"IN","dataType":"VARCHAR"},"Locations":{"column":"COALESCE(location.[BOTTOM_MICROSERVICE_NAME],location.[BOTTOM_LOCATION_NAME])","type":"IN","dataType":"VARCHAR"},"Mods":{"column":"","type":"IN","dataType":"VARCHAR"},"Occasions":{"column":"","type":"IN","dataType":"VARCHAR"},"ProductCategories":{"column":"","type":"IN","dataType":"VARCHAR"},"Products":{"column":"","type":"IN","dataType":"VARCHAR"},"ProductsComp":{"column":"","type":"IN","dataType":"VARCHAR"},"RedLionDayOfWeek":{"column":"","type":"IN","dataType":"VARCHAR"},"RedLionLocations":{"column":"","type":"IN","dataType":"VARCHAR"},"RedLionPayments":{"column":"","type":"IN","dataType":"VARCHAR"},"RedLionProducts":{"column":"","type":"IN","dataType":"VARCHAR"},"RedLionRevC":{"column":"","type":"IN","dataType":"VARCHAR"},"RedLionStaff":{"column":"","type":"IN","dataType":"VARCHAR"},"RedLionXProd":{"column":"","type":"IN","dataType":"VARCHAR"},"RedLionYProd":{"column":"","type":"IN","dataType":"VARCHAR"},"RevenueCentres":{"column":"","type":"IN","dataType":"VARCHAR"},"ServiceCharges":{"column":"","type":"IN","dataType":"VARCHAR"},"Suppliers":{"column":"","type":"IN","dataType":"VARCHAR"},"SurveyFilter":{"column":"","type":"IN","dataType":"VARCHAR"},"SurveyFilterAge":{"column":"","type":"IN","dataType":"VARCHAR"},"Tax":{"column":"","type":"IN","dataType":"VARCHAR"},"Tenders":{"column":"","type":"IN","dataType":"VARCHAR"}}',
