-- DataSetName=InvUseAnalisys / VisualizationType=CustomDataGrid
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'InvUseAnalisys' AND [VisualizationType] = N'CustomDataGrid')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 5,
        [Status] = N'LIVE',
        [QueryTemplate] = N'WITH Counts AS

(
SELECT

    SUB.*
    ,DATEDIFF(DAY,GETDATE(),[COUNT_DATE]) AS COUNT_RECENCY
FROM
    (
    SELECT
        FC.*
        ,invitem.BOTTOM_LEVEL_NAME
        ,invitem.MIDDLE_1_LEVEL_NAME
        ,invitem.TOP_LEVEL_NAME
        ,AVG(FC.DAYS_SINCE_LAST_COUNT) OVER(PARTITION BY FC.LOCATION_HUB_ID, FC.INVITEM_HUB_ID) AS COUNT_FREQUENCY
        ,ROW_NUMBER() OVER(PARTITION BY FC.LOCATION_HUB_ID, FC.INVITEM_HUB_ID ORDER BY FC.[COUNT_DATE] DESC) AS RN
        ,COALESCE(location.[BOTTOM_MICROSERVICE_NAME],location.[BOTTOM_LOCATION_NAME]) AS LOCATION_NAME
        ,COALESCE(invitem.[BOTTOM_MICROSERVICE_NAME],invitem.[BOTTOM_INVITEM_NAME]) AS INVITEM
        ,PREVIOUS_COUNT + ORDER_QTY + PRODUCTION_QTY + TRANSFER_QTY + WASTE_QTY - ACTUAL_COUNT AS ACTUAL_USED
    
   FROM
        [presentation].[F_INV_COUNTS_DAY] FC
    INNER JOIN
        [presentation].[CALENDAR] C
    ON FC.[COUNT_DATE] = C.[DATE]

    LEFT JOIN
        [presentation].[D_LOCATION] location
    ON FC.LOCATION_HUB_ID = location.BOTTOM_HUB_ID

    LEFT JOIN
        [presentation].[D_INVITEM] invitem
    ON FC.INVITEM_HUB_ID = invitem.BOTTOM_HUB_ID

    WHERE 1=1
    AND invitem.BOTTOM_INVITEM_NAME IS NOT NULL

@FilterClause
    ) SUB
WHERE RN = 1
)

SELECT
LOCATION_NAME AS Column1,
TOP_LEVEL_NAME AS Column2,
MIDDLE_1_LEVEL_NAME AS Column3,
BOTTOM_LEVEL_NAME AS Column4,
INVITEM AS Column5,
COUNT_FREQUENCY AS Column6,
COUNT_RECENCY AS Column7,
COUNT_DATE AS Column8,
DATEADD(DAY,DAYS_SINCE_LAST_COUNT * -1,COUNT_DATE)  AS Column9,
ACTUAL_COUNT AS Column10,
ORDER_QTY AS Column11,
PRODUCTION_QTY AS Column12,
TRANSFER_QTY AS Column13,
WASTE_QTY AS Column14,
PREVIOUS_COUNT AS Column15,
ACTUAL_USED  AS Column16,
SALE_QTY * -1 AS Column17,
ACTUAL_USED AS Column18,
(ACTUAL_USED ) * UOM_COST AS Column19,
NULL AS Column20,
NULL AS Column21,
NULL AS Column22,
NULL AS Column23,
NULL AS Column24,
NULL AS Column25,
NULL AS Column26,
NULL AS Column27,
NULL AS Column28,
NULL AS Column29
FROM
    Counts

