  }
}',
        [Description] = NULL,
        [CreatedDate] = '2026-01-20 11:55:43.376',
        [ModifiedDate] = '2026-01-20 11:55:43.376',
        [CreatedBy] = N'andrew.kaplan@threerocks.co.uk',
        [ModifiedBy] = N'andrew.kaplan@threerocks.co.uk',
        [OutputDefinitions] = N'{}',
        [ExecutionQuery] = NULL
    WHERE [DataSetName] = N'NetSales' AND [VisualizationType] = N'BarChartCard';
END
