-- DataSetName=NetSales / VisualizationType=StackedBarChartCard
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'NetSales' AND [VisualizationType] = N'StackedBarChartCard')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'SELECT
	XAxisLabel
	,ROW_NUMBER() OVER(ORDER BY XAxisLabel) AS LabelSort
	,Value
	,ROW_NUMBER() OVER(ORDER BY Value) AS ValueSort
	,VisId
	,Stack
FROM
(
SELECT
	C.CalendarDate AS XAxisLabel,
	ROUND(SUM(CAST([NET_TOTAL] AS FLOAT)),2) AS Value,
	''Net Sales'' AS VisId,
	''A'' AS Stack
FROM
	[threerocks].[dbo].[CShopProductSales] F
INNER JOIN
	[threerocks].[dbo].Calendar C
ON F.POSTX_DATE = C.CalendarDate

WHERE 1=1
@FilterClause

GROUP BY C.CalendarDate

UNION ALL

SELECT
	C.CalendarDate AS XAxisLabel,
	ROUND(SUM(CAST([DISCOUNT_TOTAL] AS FLOAT)),2) AS Value,
	''Discount'' AS VisId,
	''A'' AS Stack
FROM
	[threerocks].[dbo].[CShopProductSales] F
INNER JOIN
	[threerocks].[dbo].Calendar C
ON F.POSTX_DATE = C.LastWeekDate

WHERE 1=1
@FilterClause

GROUP BY C.CalendarDate

UNION ALL

SELECT
	C.CalendarDate AS XAxisLabel,
	ROUND(SUM(CAST([ITEM_COUNT] AS FLOAT)),2) AS Value,
	''Item Count'' AS VisId,
	''A'' AS Stack
FROM
	[threerocks].[dbo].[CShopProductSales] F
INNER JOIN
	[threerocks].[dbo].Calendar C
ON F.POSTX_DATE = C.LastYearDate

WHERE 1=1
@FilterClause

GROUP BY C.CalendarDate
) SUB
 
 
