-- DataSetName=OakVineCompWoWByLocation / VisualizationType=BarChartCard
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'OakVineCompWoWByLocation' AND [VisualizationType] = N'BarChartCard')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'WITH loc_weekly AS (
    SELECT
        COALESCE(location.[BOTTOM_MICROSERVICE_NAME], location.[BOTTOM_LOCATION_NAME]) AS loc_name,
        SUM(CASE WHEN C.[Year]*100+C.[Week] = mw.max_week THEN F.NET_VALUE ELSE 0 END) AS this_week,
        SUM(CASE WHEN C.[Year]*100+C.[Week] = mw.max_week - 1 THEN F.NET_VALUE ELSE 0 END) AS last_week
    FROM [presentation].[F_LINEITEM_15MIN] F
    INNER JOIN [presentation].[CALENDAR] C ON F.[ORDER_DATE] = C.[DATE]
    LEFT JOIN [presentation].[D_LOCATION] location ON F.LOCATION_HUB_ID = location.BOTTOM_HUB_ID
    CROSS JOIN (SELECT MAX(C2.[Year]*100+C2.[Week]) AS max_week FROM [presentation].[CALENDAR] C2 INNER JOIN [presentation].[F_LINEITEM_15MIN] F2 ON F2.[ORDER_DATE] = C2.[DATE] WHERE F2.LI_TYPE = ''PROD'') mw
    WHERE 1=1
    AND F.LI_TYPE <> ''TAX''
    AND location.[BOTTOM_LOCATION_NAME] <> ''Unknown''
    @FilterClause
    GROUP BY COALESCE(location.[BOTTOM_MICROSERVICE_NAME], location.[BOTTOM_LOCATION_NAME])
)
SELECT
    loc_name AS BarLabel,
    ROW_NUMBER() OVER(ORDER BY ROUND((this_week - last_week) * 100.0 / NULLIF(last_week, 0), 1) DESC) AS BarLabelSort,
    ROUND((this_week - last_week) * 100.0 / NULLIF(last_week, 0), 1) AS BarValue,
    ROUND((this_week - last_week) * 100.0 / NULLIF(last_week, 0), 1) AS BarValueSort
FROM loc_weekly

SELECT
    ''Location'' AS XAxisLabel,
    ''WoW Change %'' AS YAxisLabel,
    ''Week-over-Week by Location'' AS Title,
    NULL AS Description,
    NULL AS Trend,
    NULL AS TotalValue,
