BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'SELECT XAxisLabel, LabelSort, Value, ValueSort, VisId, Curve, Stack, Area, StackOrder, ShowMark, LegendLabel
FROM (
    SELECT
        ''W'' + CAST(C.[Week] AS VARCHAR) + '' '' + CAST(C.[Year] AS VARCHAR) AS XAxisLabel,
        C.[Year] * 100 + C.[Week] AS LabelSort,
        ROUND(SUM(FS.NET_SALES), 0) AS Value,
        1 AS ValueSort,
        1 AS VisId,
        ''linear'' AS Curve, ''total'' AS Stack, ''false'' AS Area, ''descending'' AS StackOrder, ''false'' AS ShowMark,
        ''Net Sales'' AS LegendLabel
    FROM [presentation].[F_INV_SALES_DAY] FS
    INNER JOIN [presentation].[CALENDAR] C ON CAST(FS.[INV_DATE] AS DATE) = C.[DATE]
    LEFT JOIN [presentation].[D_LOCATION] location ON FS.LOCATION_HUB_ID = location.BOTTOM_HUB_ID
    LEFT JOIN [presentation].[D_INVITEM] invitem ON FS.INVITEM_HUB_ID = invitem.BOTTOM_HUB_ID
    WHERE 1=1
    AND invitem.[BOTTOM_INVITEM_NAME] IS NOT NULL
    AND location.[BOTTOM_LOCATION_NAME] <> ''Unknown''
    AND FS.NET_SALES > 0
    @FilterClause
    GROUP BY C.[Year], C.[Week]
    UNION ALL
    SELECT
        ''W'' + CAST(C.[Week] AS VARCHAR) + '' '' + CAST(C.[Year] AS VARCHAR),
        C.[Year] * 100 + C.[Week],
        ROUND(SUM(FS.SALES_RECIPE_COST), 0),
        1,
        2,
        ''linear'', ''total'', ''false'', ''descending'', ''false'',
        ''Recipe Cost''
    FROM [presentation].[F_INV_SALES_DAY] FS
    INNER JOIN [presentation].[CALENDAR] C ON CAST(FS.[INV_DATE] AS DATE) = C.[DATE]
    LEFT JOIN [presentation].[D_LOCATION] location ON FS.LOCATION_HUB_ID = location.BOTTOM_HUB_ID
    LEFT JOIN [presentation].[D_INVITEM] invitem ON FS.INVITEM_HUB_ID = invitem.BOTTOM_HUB_ID
    WHERE 1=1
    AND invitem.[BOTTOM_INVITEM_NAME] IS NOT NULL
    AND location.[BOTTOM_LOCATION_NAME] <> ''Unknown''
    AND FS.NET_SALES > 0
    @FilterClause
    GROUP BY C.[Year], C.[Week]
) SUB

