-- DataSetName=OakVineCountsDetail / VisualizationType=CustomDataGrid
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'OakVineCountsDetail' AND [VisualizationType] = N'CustomDataGrid')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'SELECT
    COALESCE(location.[BOTTOM_MICROSERVICE_NAME], location.[BOTTOM_LOCATION_NAME]) AS Column1,
    COALESCE(invitem.[MIDDLE_1_MICROSERVICE_NAME], invitem.[MIDDLE_1_NAME]) AS Column2,
    COALESCE(invitem.[BOTTOM_MICROSERVICE_NAME], invitem.[BOTTOM_INVITEM_NAME]) AS Column3,
    CASE WHEN MAX(FC.STANDARDISED_UOM) = ''ml'' THEN ''L''
         WHEN MAX(FC.STANDARDISED_UOM) IN (''g'',''gr'') THEN ''kg''
         ELSE MAX(FC.STANDARDISED_UOM) END AS Column4,
    CASE WHEN MAX(FC.STANDARDISED_UOM) IN (''ml'',''g'',''gr'')
         THEN ROUND(SUM(FC.PREVIOUS_COUNT) / 1000.0, 2)
         ELSE ROUND(SUM(FC.PREVIOUS_COUNT), 2) END AS Column5,
    CASE WHEN MAX(FC.STANDARDISED_UOM) IN (''ml'',''g'',''gr'')
         THEN ROUND(SUM(FC.ACTUAL_COUNT) / 1000.0, 2)
         ELSE ROUND(SUM(FC.ACTUAL_COUNT), 2) END AS Column6,
    CASE WHEN MAX(FC.STANDARDISED_UOM) IN (''ml'',''g'',''gr'')
         THEN ROUND(SUM(FC.THEO_QTY) / 1000.0, 2)
         ELSE ROUND(SUM(FC.THEO_QTY), 2) END AS Column7,
    CASE WHEN MAX(FC.STANDARDISED_UOM) IN (''ml'',''g'',''gr'')
         THEN ROUND(SUM(FC.VARIANCE) / 1000.0, 2)
         ELSE ROUND(SUM(FC.VARIANCE), 2) END AS Column8,
    MAX(FC.DAYS_SINCE_LAST_COUNT) AS Column9,
    NULL AS Column10,
    NULL AS Column11,
    NULL AS Column12,
    NULL AS Column13,
    NULL AS Column14,
    NULL AS Column15,
    NULL AS Column16,
    NULL AS Column17,
    NULL AS Column18,
    NULL AS Column19,
    NULL AS Column20,
    NULL AS Column21,
    NULL AS Column22,
    NULL AS Column23,
    NULL AS Column24,
    NULL AS Column25,
    NULL AS Column26,
    NULL AS Column27,
    NULL AS Column28,
    NULL AS Column29
FROM [presentation].[F_INV_COUNTS_DAY] FC
INNER JOIN [presentation].[CALENDAR] C ON CAST(FC.[COUNT_DATE] AS DATE) = C.[DATE]
LEFT JOIN [presentation].[D_LOCATION] location ON FC.LOCATION_HUB_ID = location.BOTTOM_HUB_ID
LEFT JOIN [presentation].[D_INVITEM] invitem ON FC.INVITEM_HUB_ID = invitem.BOTTOM_HUB_ID
WHERE 1=1
AND invitem.[BOTTOM_INVITEM_NAME] IS NOT NULL
AND location.[BOTTOM_LOCATION_NAME] <> ''Unknown''
@FilterClause
GROUP BY
    COALESCE(location.[BOTTOM_MICROSERVICE_NAME], location.[BOTTOM_LOCATION_NAME]),
    COALESCE(invitem.[MIDDLE_1_MICROSERVICE_NAME], invitem.[MIDDLE_1_NAME]),
    COALESCE(invitem.[BOTTOM_MICROSERVICE_NAME], invitem.[BOTTOM_INVITEM_NAME])

