-- DataSetName=OakVineInvWasteTrend / VisualizationType=MultiLineChartCard
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'OakVineInvWasteTrend' AND [VisualizationType] = N'MultiLineChartCard')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'SELECT
    ''W'' + CAST(C.[Week] AS VARCHAR) + '' '' + CAST(C.[Year] AS VARCHAR) AS XAxisLabel,
    C.[Year] * 100 + C.[Week] AS LabelSort,
    ROUND(SUM(ABS(FU.WASTE_QTY) * FU.UOM_COST), 0) AS Value,
    1 AS ValueSort,
    ROW_NUMBER() OVER(PARTITION BY C.[Year], C.[Week] ORDER BY SUM(ABS(FU.WASTE_QTY) * FU.UOM_COST) DESC) AS VisId,
    ''linear'' AS Curve,
    ''total'' AS Stack,
    ''false'' AS Area,
    ''descending'' AS StackOrder,
    ''false'' AS ShowMark,
    COALESCE(invitem.[MIDDLE_1_MICROSERVICE_NAME], invitem.[MIDDLE_1_NAME]) AS LegendLabel
FROM [presentation].[F_INV_USAGE_DAY] FU
INNER JOIN [presentation].[CALENDAR] C ON CAST(FU.COUNT_DATE AS DATE) = C.[DATE]
LEFT JOIN [presentation].[D_INVITEM] invitem ON FU.INVITEM_HUB_ID = invitem.BOTTOM_HUB_ID
LEFT JOIN [presentation].[D_LOCATION] location ON FU.LOCATION_HUB_ID = location.BOTTOM_HUB_ID
WHERE 1=1
AND FU.UOM_COST IS NOT NULL
AND location.[BOTTOM_LOCATION_NAME] <> ''Unknown''
@FilterClause
GROUP BY C.[Year], C.[Week], COALESCE(invitem.[MIDDLE_1_MICROSERVICE_NAME], invitem.[MIDDLE_1_NAME])
HAVING SUM(ABS(FU.WASTE_QTY) * FU.UOM_COST) > 0

