IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'OakVineMarginByCategory' AND [VisualizationType] = N'CombinedChartCard')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'SELECT XAxisLabel, LabelSort, Value, ValueSort, VisId, VisType, LegendLabel
FROM (
    SELECT
        COALESCE(product.[MIDDLE_1_MICROSERVICE_NAME], product.[MIDDLE_1_NAME]) AS XAxisLabel,
        ROW_NUMBER() OVER(ORDER BY SUM(F.NET_VALUE) DESC) AS LabelSort,
        ROUND(SUM(F.NET_VALUE), 0) AS Value,
        1 AS ValueSort,
        1 AS VisId,
        ''bar'' AS VisType,
        ''Revenue'' AS LegendLabel
    FROM [presentation].[F_PRODUCT_MARGIN_DAY] F
    INNER JOIN [presentation].[CALENDAR] C ON F.[ORDER_DATE] = C.[DATE]
    LEFT JOIN [presentation].[D_PRODUCT] product ON F.PRODUCT_HUB_ID = product.BOTTOM_HUB_ID
    LEFT JOIN [presentation].[D_LOCATION] location ON F.LOCATION_HUB_ID = location.BOTTOM_HUB_ID
    WHERE 1=1
    AND product.[MIDDLE_1_NAME] IS NOT NULL AND product.[MIDDLE_1_NAME] <> ''Unknown''
    @FilterClause
    GROUP BY COALESCE(product.[MIDDLE_1_MICROSERVICE_NAME], product.[MIDDLE_1_NAME])

    UNION ALL

    SELECT
        COALESCE(product.[MIDDLE_1_MICROSERVICE_NAME], product.[MIDDLE_1_NAME]) AS XAxisLabel,
        ROW_NUMBER() OVER(ORDER BY SUM(F.NET_VALUE) DESC) AS LabelSort,
        ROUND(SUM(F.PROFIT) * 100.0 / NULLIF(SUM(F.NET_VALUE), 0), 1) AS Value,
        1 AS ValueSort,
        2 AS VisId,
        ''line'' AS VisType,
        ''GP %'' AS LegendLabel
    FROM [presentation].[F_PRODUCT_MARGIN_DAY] F
    INNER JOIN [presentation].[CALENDAR] C ON F.[ORDER_DATE] = C.[DATE]
    LEFT JOIN [presentation].[D_PRODUCT] product ON F.PRODUCT_HUB_ID = product.BOTTOM_HUB_ID
    LEFT JOIN [presentation].[D_LOCATION] location ON F.LOCATION_HUB_ID = location.BOTTOM_HUB_ID
    WHERE 1=1
    AND product.[MIDDLE_1_NAME] IS NOT NULL AND product.[MIDDLE_1_NAME] <> ''Unknown''
    @FilterClause
    GROUP BY COALESCE(product.[MIDDLE_1_MICROSERVICE_NAME], product.[MIDDLE_1_NAME])
) sub

