-- DataSetName=ParentBkgBrandGrowth / VisualizationType=SingleKPICard
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'ParentBkgBrandGrowth' AND [VisualizationType] = N'SingleKPICard')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'WITH MonthlyData AS (
    SELECT DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1) AS MonthStart,
        SUM(TOTAL_BOOKINGS) AS Bookings
    FROM [presentation].[PF_BOOKING_METRICS_HOUR]
    WHERE 1=1 @FilterClause
    GROUP BY DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1)
    HAVING SUM(TOTAL_BOOKINGS) > 0
),
DateRange AS (
    SELECT MIN(MonthStart) AS FirstMonth, MAX(MonthStart) AS LastMonth
    FROM MonthlyData
)
SELECT TOP 1
    CASE WHEN dr.FirstMonth < dr.LastMonth
        THEN CASE WHEN GrowthPct >= 0 THEN ''+'' ELSE '''' END
             + FORMAT(GrowthPct, ''N0'') + ''%''
        ELSE ''N/A'' END AS Value,
    ''Growth'' AS Title,
    FORMAT(dr.FirstMonth, ''MMM yyyy'') + '' to '' + FORMAT(dr.LastMonth, ''MMM yyyy'') AS Subtitle
FROM (
    SELECT
        ROUND((CAST(l.Bookings AS FLOAT) - f.Bookings) / f.Bookings * 100, 0) AS GrowthPct
    FROM MonthlyData f
    CROSS JOIN MonthlyData l
    CROSS JOIN DateRange dr
    WHERE f.MonthStart = dr.FirstMonth AND l.MonthStart = dr.LastMonth
) calc
CROSS JOIN DateRange dr',
        [ParameterMappings] = N'{"LocationList": "", "StartDate": "BOOKING_DATE", "EndDate": "BOOKING_DATE"}',
        [FilterDefinitions] = N'{"Brands": {"column": "BRAND_NAME", "type": "IN", "dataType": "VARCHAR"}}',
        [Description] = N'Percentage growth from first to last month for selected brand',
        [CreatedDate] = '2026-04-09 09:56:30.680',
        [ModifiedDate] = '2026-04-09 09:56:30.680',
        [CreatedBy] = N'mushfiqur.rahman@threerocks.co.uk',
        [ModifiedBy] = N'mushfiqur.rahman@threerocks.co.uk',
        [OutputDefinitions] = N'{"column_mappings": {}, "additional_datasets": []}',
        [ExecutionQuery] = NULL
    WHERE [DataSetName] = N'ParentBkgBrandGrowth' AND [VisualizationType] = N'SingleKPICard';
END
ELSE
BEGIN
    INSERT INTO [core].[core].[VisualisationQueries] ([DataSetName], [VisualizationType], [Version], [Status], [QueryTemplate], [ParameterMappings], [FilterDefinitions], [Description], [CreatedDate], [ModifiedDate], [CreatedBy], [ModifiedBy], [OutputDefinitions], [ExecutionQuery])
    VALUES (N'ParentBkgBrandGrowth', N'SingleKPICard', 1, N'LIVE', N'WITH MonthlyData AS (
    SELECT DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1) AS MonthStart,
        SUM(TOTAL_BOOKINGS) AS Bookings
    FROM [presentation].[PF_BOOKING_METRICS_HOUR]
    WHERE 1=1 @FilterClause
    GROUP BY DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1)
    HAVING SUM(TOTAL_BOOKINGS) > 0
),
DateRange AS (
    SELECT MIN(MonthStart) AS FirstMonth, MAX(MonthStart) AS LastMonth
    FROM MonthlyData
)
SELECT TOP 1
    CASE WHEN dr.FirstMonth < dr.LastMonth
        THEN CASE WHEN GrowthPct >= 0 THEN ''+'' ELSE '''' END
             + FORMAT(GrowthPct, ''N0'') + ''%''
        ELSE ''N/A'' END AS Value,
    ''Growth'' AS Title,
    FORMAT(dr.FirstMonth, ''MMM yyyy'') + '' to '' + FORMAT(dr.LastMonth, ''MMM yyyy'') AS Subtitle
FROM (
    SELECT
        ROUND((CAST(l.Bookings AS FLOAT) - f.Bookings) / f.Bookings * 100, 0) AS GrowthPct
    FROM MonthlyData f
    CROSS JOIN MonthlyData l
    CROSS JOIN DateRange dr
    WHERE f.MonthStart = dr.FirstMonth AND l.MonthStart = dr.LastMonth
) calc
CROSS JOIN DateRange dr', N'{"LocationList": "", "StartDate": "BOOKING_DATE", "EndDate": "BOOKING_DATE"}', N'{"Brands": {"column": "BRAND_NAME", "type": "IN", "dataType": "VARCHAR"}}', N'Percentage growth from first to last month for selected brand', '2026-04-09 09:56:30.680', '2026-04-09 09:56:30.680', N'mushfiqur.rahman@threerocks.co.uk', N'mushfiqur.rahman@threerocks.co.uk', N'{"column_mappings": {}, "additional_datasets": []}', NULL);
