    FROM [presentation].[PF_BOOKING_METRICS_HOUR]
    WHERE 1=1 @FilterClause
    GROUP BY DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1)

    UNION ALL

    SELECT
        FORMAT(DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1), ''MMM yyyy''),
        DATEFROMPARTS(YEAR(BOOKING_DATE), MONTH(BOOKING_DATE), 1),
        SUM(TOTAL_COVERS),
        ''Covers'',
        ''B''
