        [ModifiedBy] = N'dbadmin',
        [OutputDefinitions] = N'{
  "column_mappings": {},
  "additional_datasets": []
}',
        [ExecutionQuery] = NULL
    WHERE [DataSetName] = N'ParentDiscountImpact' AND [VisualizationType] = N'BarChartCard';
END
