    NULL AS Column22,
    NULL AS Column23,
    NULL AS Column24,
    NULL AS Column25,
    NULL AS Column26,
    NULL AS Column27,
    NULL AS Column28,
    NULL AS Column29
FROM rev_cte rev
LEFT JOIN pft_cte pft ON pft.ORG_CODE = rev.ORG_CODE
LEFT JOIN fc_cte fc ON fc.ORG_CODE = rev.ORG_CODE
LEFT JOIN eff_cte eff ON eff.ORG_CODE = rev.ORG_CODE


