--TAX_TOTAL AS Column8,
 

FROM (
SELECT [POSTX_DATE]
      --,[NAME] AS STORENAME
      --,[DAY_PERIOD]
      --,[PRODUCT_TYPE]
      ,SUM(CAST([ITEM_COUNT] AS INT)) AS ITEMS_SOLD
      ,ROUND(SUM(CAST([CHECK_TOTAL] AS FLOAT)),2) AS SALES_TOTAL
