      CAST (ROUND(SUM(CASE WHEN ORDER_TYPE = ''Deliveroo'' THEN CAST([CHECK_TOTAL] AS FLOAT)  ELSE 0 END),2 ) AS NVARCHAR(20) ) + '','' +
