        [CreatedBy] = N'andrew.kaplan@threerocks.co.uk',
        [ModifiedBy] = N'andrew.kaplan@threerocks.co.uk',
        [OutputDefinitions] = N'{}',
        [ExecutionQuery] = NULL
    WHERE [DataSetName] = N'ProductNetSales' AND [VisualizationType] = N'CustomPinnedDataGrid';
END
