    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'WITH Base AS
    (
    SELECT 
        COUNT(DISTINCT [Transaction_ID]) AS Transaction_Count,
        COUNT(*) AS Item_Count,
        SUM(CASE WHEN [Item_Name] = ''Gratuity'' THEN [Item_Value] ELSE 0 END) AS Gratuity,
        SUM(CASE WHEN [Item_Name] = ''Gratuity'' THEN [Item_Value] ELSE 0 END) /
        SUM(CASE WHEN [Item_Name] != ''Gratuity'' THEN [Item_Value] + [Item_Tax_Value] ELSE 0 END) AS Perc_of_Gross
    FROM
        (
        SELECT
            *
        FROM
            [20260202_XMS_8381A215-4601-F111-8D4C-000D3AB579E6].[stage].[RedLion_Transactions]
        WHERE [Voided] = ''FALSE''
        @FilterClause
