-- DataSetName=RedLionHourlyMix / VisualizationType=PieChartCard
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'RedLionHourlyMix' AND [VisualizationType] = N'PieChartCard')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'WITH Base AS
    (
    SELECT 
        DATEPART(HOUR, [Sold_Time]) AS TIME_HOUR,
        COUNT(DISTINCT [Transaction_ID]) AS Transaction_Count,
        COUNT(DISTINCT [Transaction_ID])/COUNT(DISTINCT [Trading_Date]) AS Avg_Transaction_Count,
        COUNT(*) AS Item_Count,
        COUNT(*)/COUNT(DISTINCT [Trading_Date]) AS Avg_Item_Count,
        SUM([Item_Value]) AS Total_Revenue,
        SUM([Item_Value])/COUNT(DISTINCT [Trading_Date]) AS Avg_Total_Revenue,
        SUM([Item_Value] + [Item_Tax_Value]) AS Total_Revenue_Inc_Tax,
        SUM([Item_Value])/COUNT(DISTINCT [Transaction_ID]) AS Avg_Tx_Value
    FROM
        (
        SELECT
            *
        FROM
            [20260202_XMS_8381A215-4601-F111-8D4C-000D3AB579E6].[stage].[RedLion_Transactions]
        WHERE [Voided] = ''FALSE''
        AND [Item_Name] != ''Gratuity''
	@FilterClause
        ) SUB
    GROUP BY DATEPART(HOUR, [Sold_Time])
    )


SELECT
	Label,
	Value,
	Id,
	''linear'' AS Curve,
	''total'' AS Stack,
	''true'' AS Area,
	''ascending'' AS StackOrder,
	''false'' AS ShowMark,
	''Percent'' AS LegendLabel
FROM

(
SELECT
    TIME_HOUR AS Label
    ,ROUND(Total_Revenue, 0) AS Value
    ,2 AS Id
FROM
    BASE
) SUB

