    "dataType": "VARCHAR"
  },
  "Tax": {
    "column": "",
    "type": "IN",
    "dataType": "VARCHAR"
  },
  "Tenders": {
    "column": "",
    "type": "IN",
    "dataType": "VARCHAR"
  }
}', NULL, '2026-02-04 00:07:38.436', '2026-02-06 09:57:35.653', N'dbadmin', N'dbadmin', N'{
  "column_mappings": {
    "XAxisLabel": "XAxisLabel",
    "LabelSort": "LabelSort",
    "Value": "Value",
    "ValueSort": "ValueSort",
    "VisId": "VisId",
    "VisType": "VisType",
    "LegendLabel": "LegendLabel"
  },
  "additional_datasets": [
    {
      "name": "Header1",
      "type": "Header",
      "columns": [
        "XAxisLabel",
        "YAxisLabel",
        "Title",
        "Description"
      ],
      "values": {
        "XAxisLabel": "Time of Day",
        "YAxisLabel": "",
        "Title": "ATV vs Item Count Daily Pattern",
        "Description": ""
      }
    }
  ]
}', N'WITH Base AS
    (
    SELECT 
        DATEPART(HOUR, [Sold_Time]) AS [TIME_15_MIN],
        COUNT(DISTINCT [Transaction_ID]) AS Transaction_Count,
        COUNT(DISTINCT [Transaction_ID])/COUNT(DISTINCT [Trading_Date]) AS Avg_Transaction_Count,
        COUNT(*) AS Item_Count,
        COUNT(*)/COUNT(DISTINCT [Trading_Date]) AS Avg_Item_Count,
        SUM([Item_Value]) AS Total_Revenue,
        SUM([Item_Value] + [Item_Tax_Value]) AS Total_Revenue_Inc_Tax,
        SUM([Item_Value])/COUNT(DISTINCT [Transaction_ID]) AS Avg_Tx_Value
    FROM
        (
        SELECT
            *
        FROM
            [20260202_XMS_8381A215-4601-F111-8D4C-000D3AB579E6].[stage].[RedLion_Transactions]
        WHERE [Voided] = ''FALSE''
        AND [Item_Name] != ''Gratuity''
	@FilterClause
        ) SUB
    GROUP BY DATEPART(HOUR, [Sold_Time])
    )
SELECT
    [XAxisLabel] AS [XAxisLabel]
    ,    [LabelSort] AS [LabelSort]
    ,    [Value] AS [Value]
    ,    [ValueSort] AS [ValueSort]
    ,    [VisId] AS [VisId]
    ,    [VisType] AS [VisType]
    ,    [LegendLabel] AS [LegendLabel]
FROM
(
SELECT
    CONVERT(NVARCHAR,XAxisLabel) AS XAxisLabel
    ,DENSE_RANK() OVER(ORDER BY XAxisLabel) AS LabelSort
    ,Value
    ,DENSE_RANK() OVER(ORDER BY Value) AS ValueSort
    ,VisId
    ,VisType
    ,LegendLabel
FROM
(SELECT
        [TIME_15_MIN] AS XAxisLabel,
        ROUND(Avg_Transaction_Count,2) AS Value,
        2 AS VisId,
        ''line'' AS VisType,
        ''Avg. Transaction Volume'' AS LegendLabel
    FROM
        Base

    UNION ALL

    SELECT
        [TIME_15_MIN] AS XAxisLabel,
        ROUND(Avg_Tx_Value,2) AS Value,
        3 AS VisId,
        ''line'' AS VisType,
        ''Avg. Transaction Value'' AS LegendLabel
    FROM
        Base
    ) SUB
) INPUTQUERY

SELECT
    ''Time of Day'' AS [XAxisLabel]
    ,    NULL AS [YAxisLabel]
    ,    ''ATV vs Item Count Daily Pattern'' AS [Title]
    ,    NULL AS [Description]');
END
