    VALUES (N'RedLionTop20', N'StackedBarChartCard', 1, N'LIVE', N'WITH base_data AS (
    SELECT [Location_Name], [Revenue_Center], [Transaction_ID], [ORDER_ID], 
           [Trading_Date], [Sold_Time], [TIME_15_MIN], [Item_Count], [User_Name],
           [Item_ID], [Item_Name], [Item_Value], [Item_Tax_Value], [Voided],
           [Sub_Group_Name], [Group_Name], [Category_Name], [Payment_Type], [GRATUITY_FLAG]
    FROM [20260202_XMS_8381A215-4601-F111-8D4C-000D3AB579E6].[stage].[RedLion_Transactions]
    WHERE [Voided] = ''FALSE''
    AND [Item_ID] > 0
    @FilterClause
    ),

Final AS (
SELECT TOP 20
    [Item_Name],
    [Sub_Group_Name],
    [Group_Name],
    COUNT(*) AS Units_Sold,
    SUM([Item_Value]) AS Total_Revenue,
    SUM([Item_Value] + [Item_Tax_Value]) AS Total_Revenue_Inc_Tax,
    AVG([Item_Value]) AS Avg_Price,
    COUNT(DISTINCT [Transaction_ID]) AS Transactions_Appeared_In
FROM base_data
GROUP BY [Item_Name], [Sub_Group_Name], [Group_Name]
ORDER BY Total_Revenue DESC
)

select 
xAxisLabel,
ROW_NUMBER() OVER(ORDER BY [Value] DESC) AS LabelSort,
[Value],
ROW_NUMBER() OVER(ORDER BY [Value] DESC) AS ValueSort,
VisId,
Stack
from    (    SELECT TOP 20
        [Item_Name] AS XAxisLabel,
        Units_Sold AS Value,
        ''Items Sold'' AS VisId,
        ''A'' AS Stack
    FROM Final    UNION ALL    SELECT TOP 20
        [Item_Name] AS XAxisLabel,
        Total_Revenue AS Value,
        ''Revenue'' AS VisId,
        ''B'' AS Stack
    FROM Final
    ) sub 
