        [ExecutionQuery] = N'WITH Base AS
    (
    SELECT 
        CONCAT_WS(''-'', [Day_Of_Week], DATEPART(HOUR, [Sold_Time])) AS [TIME_15_MIN],
        CASE
            WHEN [Day_Of_Week] = ''Monday'' THEN 100
            WHEN [Day_Of_Week] = ''Tuesday'' THEN 200
            WHEN [Day_Of_Week] = ''Wednesday'' THEN 300
            WHEN [Day_Of_Week] = ''Thursday'' THEN 400
            WHEN [Day_Of_Week] = ''Friday'' THEN 500
            WHEN [Day_Of_Week] = ''Saturday'' THEN 600
            WHEN [Day_Of_Week] = ''Sunday'' THEN 700
        END + DATEPART(HOUR, [Sold_Time]) AS X_SORT,
        COUNT(DISTINCT [Transaction_ID]) AS Transaction_Count,
        COUNT(DISTINCT [Transaction_ID])/COUNT(DISTINCT [Trading_Date]) AS Avg_Transaction_Count,
        COUNT(*) AS Item_Count,
        COUNT(*)/COUNT(DISTINCT [Trading_Date]) AS Avg_Item_Count,
        SUM([Item_Value]) AS Total_Revenue,
        SUM([Item_Value])/COUNT(DISTINCT [Trading_Date]) AS Avg_Total_Revenue,
        SUM([Item_Value] + [Item_Tax_Value]) AS Total_Revenue_Inc_Tax,
        SUM([Item_Value])/COUNT(DISTINCT [Transaction_ID]) AS Avg_Tx_Value
    FROM
        (
        SELECT
            *
        FROM
            [20260202_XMS_8381A215-4601-F111-8D4C-000D3AB579E6].[stage].[RedLion_Transactions]
        WHERE [Voided] = ''FALSE''
        AND [Item_Name] != ''Gratuity''
	@FilterClause
        ) SUB
    GROUP BY [Day_Of_Week],DATEPART(HOUR, [Sold_Time]), CONCAT_WS(''-'', [Day_Of_Week], DATEPART(HOUR, [Sold_Time]))
    )
