	[Item_Name] AS [PRODUCT_NAME]
	,[Item_Name] AS [PRODUCT_ID]
	,ISNULL([Sub_Group_Name], ''Not Grouped'') AS [PARENT_ID]
	,1 AS [BOTTOM_LEVEL]
FROM [20260202_XMS_8381A215-4601-F111-8D4C-000D3AB579E6].[stage].[RedLion_Transactions] a
INNER JOIN
	[20260202_XMS_8381A215-4601-F111-8D4C-000D3AB579E6].[stage].[RedLion_ProdAttachment] b
ON a.Item_Name = b.PRODUCT_HUB_ID
WHERE [Item_ID] > 0
UNION ALL

SELECT DISTINCT
	[Sub_Group_Name] AS [PRODUCT_NAME]
	,[Sub_Group_Name] AS [PRODUCT_ID]
	,[Group_Name] AS [PARENT_ID]
	,0 AS [BOTTOM_LEVEL]
FROM [20260202_XMS_8381A215-4601-F111-8D4C-000D3AB579E6].[stage].[RedLion_Transactions] a
INNER JOIN
	[20260202_XMS_8381A215-4601-F111-8D4C-000D3AB579E6].[stage].[RedLion_ProdAttachment] b
ON a.Item_Name = b.PRODUCT_HUB_ID
WHERE [Sub_Group_Name] IS NOT NULL

UNION ALL

SELECT DISTINCT
	[Group_Name] AS [PRODUCT_NAME]
	,[Group_Name] AS [PRODUCT_ID]
	,NULL AS [PARENT_ID]
	,0 AS [BOTTOM_LEVEL]
FROM [20260202_XMS_8381A215-4601-F111-8D4C-000D3AB579E6].[stage].[RedLion_Transactions] a
INNER JOIN
	[20260202_XMS_8381A215-4601-F111-8D4C-000D3AB579E6].[stage].[RedLion_ProdAttachment] b
ON a.Item_Name = b.PRODUCT_HUB_ID
WHERE [Group_Name] IS NOT NULL

UNION ALL

SELECT DISTINCT
	''Not Grouped'' AS [PRODUCT_NAME]
	,''Not Grouped'' AS [PRODUCT_ID]
	,NULL AS [PARENT_ID]
	,0 AS [BOTTOM_LEVEL]
) INPUTQUERY

SELECT
    ''Product Attachment - Y Axis'' AS [Title]');
END
