        [ExecutionQuery] = N'SELECT
    [ParentId] AS [ParentId]
    ,    [Id] AS [Id]
    ,    [GroupedColumn] AS [GroupedColumn]
    ,    [Column1] AS [Column1]
    ,    [Column2] AS [Column2]
    ,    [Column3] AS [Column3]
    ,    [Column4] AS [Column4]
    ,    [Column5] AS [Column5]
    ,    [Column6] AS [Column6]
FROM
(
SELECT
PARENT_ID AS ParentId,
ID AS Id,
STORENAME AS GroupedColumn,
ITEMS_SOLD AS Column1,
SALES_TOTAL AS Column2,
ATV AS Column3,
SALES_NET_TOTAL AS Column4,
DISCOUNT_TOTAL AS Column5,
TAX_TOTAL AS Column6,
NULL AS Column7,
NULL AS Column8,
NULL AS Column9,
NULL AS Column10,
NULL AS Column11,
NULL AS Column12,
NULL AS Column13,
NULL AS Column14,
