-- DataSetName=SurveyAgeByGender / VisualizationType=CustomDataGrid
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'SurveyAgeByGender' AND [VisualizationType] = N'CustomDataGrid')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'SELECT
f.AGE_BRACKET AS Column1,
SUM(CASE WHEN f.GENDER = ''Female'' THEN 1 ELSE 0 END) AS Column2,
SUM(CASE WHEN f.GENDER = ''Male'' THEN 1 ELSE 0 END) AS Column3,
SUM(CASE WHEN f.GENDER = ''Other'' THEN 1 ELSE 0 END) AS Column4,
SUM(CASE WHEN f.GENDER = ''I would rather not say'' THEN 1 ELSE 0 END) AS Column5,
COUNT(DISTINCT f.TOUCHPOINT_HUB_ID) AS Column6,
NULL AS Column7,
NULL AS Column8,
NULL AS Column9,
NULL AS Column10,
NULL AS Column11,
NULL AS Column12,
NULL AS Column13,
NULL AS Column14,
NULL AS Column15,
NULL AS Column16,
NULL AS Column17,
NULL AS Column18,
NULL AS Column19,
NULL AS Column20,
NULL AS Column21,
NULL AS Column22,
NULL AS Column23,
NULL AS Column24,
NULL AS Column25,
NULL AS Column26,
NULL AS Column27,
NULL AS Column28,
NULL AS Column29,
NULL AS Column30
FROM [presentation].[F_SURVEY_RESPONSE] f
WHERE f.TOUCHPOINT_STATUS = ''completed''
AND f.AGE_BRACKET IS NOT NULL
AND f.GENDER IS NOT NULL
AND f.QUESTION_HUB_ID = (
    SELECT TOP 1 q2.BOTTOM_HUB_ID
    FROM [presentation].[D_QUESTION] q2
    WHERE q2.BOTTOM_QUESTION_NAME = ''What age bracket are you in ?''
)
AND 1=1
@FilterClause
GROUP BY f.AGE_BRACKET


