-- DataSetName=SurveyChurchRadarChallenges / VisualizationType=RadarChartCard
IF EXISTS (SELECT 1 FROM [core].[core].[VisualisationQueries] WHERE [DataSetName] = N'SurveyChurchRadarChallenges' AND [VisualizationType] = N'RadarChartCard')
BEGIN
    UPDATE [core].[core].[VisualisationQueries]
    SET
        [Version] = 1,
        [Status] = N'LIVE',
        [QueryTemplate] = N'SELECT
q.BOTTOM_QUESTION_NAME AS Axis,
CASE WHEN q.MIDDLE_1_QUESTION_NAME LIKE ''Not called%'' THEN ''God Calling'' ELSE ''Expertise & Resource'' END AS Label,
CAST(AVG(CAST(f.ANSWER_TEXT AS DECIMAL(5,2))) AS DECIMAL(5,2)) AS Value
FROM [presentation].[F_SURVEY_RESPONSE] f
INNER JOIN [presentation].[D_QUESTION] q ON f.QUESTION_HUB_ID = q.BOTTOM_HUB_ID
WHERE f.TOUCHPOINT_STATUS = ''completed''
AND f.COMMUNITY_INVOLVEMENT = ''Church congregation member''
AND q.TOP_QUESTION_NAME = ''Challenging issues''
